class JsonRpcLayer(object):
    def __init__(self, port, host, logger, data_logger):
        super(JsonRpcLayer, self).__init__()
        self.logger = logger
        self.transport = JsonThreadedTransportMedium(port=port, host=host, logger=logger, data_logger=data_logger)
        self.protocol = JsonRpcProtocol()
        self.methodsRegistry = RpcMethodsRegistry()
        self.timeoutRegistry = RpcTimeoutRegistry()
        self.rpcClient = RpcClient(self.protocol, self.transport, self.methodsRegistry, self.timeoutRegistry, self.logger)

    def call(self, method, notification=False, timeout=3, silent=False, *args, **kwargs):
        '''
        Call requested method and return result.
        '''
        return self.rpcClient.call(method, notification, timeout, silent, *args, **kwargs)

    def debug_event(self, *args, **kwargs):
        if self.logger:
            self.logger.debug_event(*args, **kwargs)

    def is_running(self):
        '''
        Check if RPC layer is running
        '''
        rpc_status = self.rpcClient.is_running() if self.rpcClient else None
        trs_status = self.transport.is_running()
        if not rpc_status:
            self.debug_event(info="RPC DOWN", owner="[%s]" % self.__class__.__name__)
        if not trs_status:
            self.debug_event(info="TRS DOWN", owner="[%s]" % self.__class__.__name__)
        return rpc_status and trs_status

    def stop(self):
        '''
        Stop RPC layer
        '''
        if self.rpcClient:
            self.rpcClient.stop()
            self.rpcClient = None

    def register_method(self, fun, name=None):
        '''
        Add a method to the registry.
        '''
        return self.methodsRegistry.add_method(fun, name)

    def unregister_method(self, fun, name=None):
        '''
        Remove method from the registry.
        '''
        if not name:
            name = self.methodsRegistry.get_rpc_public_name(fun)
        return self.methodsRegistry.del_method(name)

    def start_timer(self, timeout, timeout_action, name=None):
        '''
        Register timer and its expiry-action inside RPC layer.
        '''
        return self.timeoutRegistry.add_method(timeout_action, timeout, name)

    def stop_timer(self, timeout_action, name=None):
        '''
        Unregister timer from RPC layer.
        '''
        if not name:
            name = self.timeoutRegistry.get_rpc_public_name(timeout_action)
        return self.timeoutRegistry.del_method(name)


class RpcMsg(object):
    ''' Base class for rpc request-response messaging.

        Base class has identity encoding - returns itself.
    '''

    def __init__(self):
        super(RpcMsg, self).__init__()

    def encode(self):
        '''
        identity == no encoding
        '''
        return self

    def __str__(self):
        encoded = self.encode()
        val = '' if encoded is self else encoded  # protect against infinite recursion
        return "%s(%s)" % (self.__class__.__name__, val)

    def __repr__(self):
        return "<%s>" % self.__str__()


class JsonRpcRequest(RpcMsg):
    def __init__(self, method, notification=False, id=None, silent=False, *args, **kwargs):
        super(JsonRpcRequest, self).__init__()
        self.method = method
        self.notification = notification
        self.args = args
        self.kwargs = kwargs
        self.id = id
        self.silent = silent
        if (not notification) and (id is None):
            raise ErrJsonIncorrectParams("JsonRpcRequest with 'notification=False' must be provided with 'id' != None")
        if self.args:
            raise ErrJsonPositionalArgsNotSupported(
                "Positional arguments not supported. Use only keyword args.")

    def encode(self):
        '''
        Encodes message into json string.
        '''
        rpc_msg = {}
#       rpc_msg['jsonrpc'] = "2.0"
#       rpc_msg['sync'] = 0
        if not self.notification:
            rpc_msg['id'] = self.id
        if self.silent:
            rpc_msg['silent'] = 1
        rpc_msg['method'] = self.method

        if self.kwargs:
            rpc_msg['params'] = self.kwargs

        return JsonEncoder.encode(rpc_msg)


class JsonRpcResponse(RpcMsg):
    def __init__(self, id, data, error):
        super(JsonRpcResponse, self).__init__()
        self.id = id
        self.result_or_err = data
        self.error = error

    def is_for(self, other):
        '''
        Corelate ids of response and request and check if response is for given request.
        '''
        return self.id == other.id

    def result(self):
        '''
        Get result or raise if error
        '''
        if self.error:
            raise ErrJsonRemoteSiteResultError(self.result_or_err)
        return self.result_or_err


class JsonRpcProtocol(object):
    def __init__(self):
        super(JsonRpcProtocol, self).__init__()
        self._req_id = 0

    def _next_id(self):
        self._req_id += 1
        return self._req_id

    def _create_rpcMsg(self, data):
        try:
            if 'id' in data and 'result' in data:
                return JsonRpcResponse(data['id'], data['result'], error=False)
            if 'id' in data and 'error' in data:
                return JsonRpcResponse(data['id'], data['error'], error=True)
            if data['method']:
                req_id = None
                if 'id' in data:
                    req_id = data['id']
                    notification = False
                else:
                    notification = True
                method = data['method']
                params = data['params']
                if isinstance(params, dict):
                    return JsonRpcRequest(method, notification, req_id, **params)
                else:
                    return JsonRpcRequest(method, notification, req_id, *params)
        except KeyError:
            print("[EXC] JsonRpcProtocol::_create_rpcMsg: Invalid json-rpc message structure.")
            raise ErrJsonRpcInvalidMsgStructure("Invalid json-rpc message structure. Message is: %s" % data)

    def create_request(self, method, notification=False, silent=False, *args, **kwargs):
        '''
        Creates request that holds information about message to be sent to remote side.
        '''
        req_id = self._next_id()
        return JsonRpcRequest(method, notification, req_id, silent, *args, **kwargs)

    def responds(self, response, request):
        '''
        Check if given response responds for given request.
        '''
        return response.is_for(request)

    def encode(self, rpc_message):
        '''
        Encodes Rpc message to protocol specific format.
        '''
        return rpc_message.encode()

    def decode(self, protocol_formated_msg):
        '''
        Decodes given json string.
        '''
        json_dict = JsonEncoder.decode(protocol_formated_msg)
        rpc_msg = self._create_rpcMsg(json_dict)
        return rpc_msg


class RpcMethodsRegistry(object):
    def __init__(self):
        super(RpcMethodsRegistry, self).__init__()
        self.registry = {}  # maps rpc-public-name to callable
        self._sequence_number = 0

    def get_rpc_public_name(self, fun):
        '''
        Using given callable (method or class instance) create public name for it.
        '''
        if hasattr(fun, '__call__'):
            assert (not hasattr(fun, '__bases__')), "method argument must be callable '%s' class instance not '%s' class" % (fun.__name__, fun.__name__)

        if hasattr(fun, '__self__') and fun.__self__:
            addr = hex(id(fun.__self__))  # address of bound method
            name = "%s.%s" % (addr, fun.__name__)
        elif (hasattr(fun, '__call__')
              and (fun.__class__.__name__ != 'function')
              and (fun.__class__.__name__ != 'builtin_function_or_method')):
            addr = hex(id(fun))  # address of class instance
            name = "%s.%s" % (addr, fun.__class__.__name__)
        else:
            name = fun.__name__
        name = "%s_%s" % (self.next_sequence_number(), name)
        return name

    def next_sequence_number(self):
        self._sequence_number += 1
        return self._sequence_number

    def add_method(self, fun, name=None):
        '''
        Add a method to the registry.
        '''

        if not name:
            name = self.get_rpc_public_name(fun)

        if name in self.registry:
            if fun == self.registry[name]:
                return name
            raise ErrRpcMethodAlreadyRegistered(name, self.registry[name], fun)
        self.registry[name] = fun
        return name

    def del_method(self, name):
        '''
        Remove method in registry.
        '''
        return self.registry.pop(name, None)

    def get_method(self, name):
        '''
        Get method from registry.
        '''
        method = None
        if name in self.registry:
            method = self.registry[name]
        elif name == "event":
            method = self._get_last_method()
        else:
            print("WARNING: JSON request with not registered method: %s" % name)
        return method

    def _get_last_method(self):
        ret = None
        methods = {}
        for name, method in self.registry.items():
            srch = re.search(r'^(\d+)_', name)
            if srch:
                methods[int(srch.group(1))] = method
        if methods:
            ret = methods[sorted(methods.keys()).pop()]
        return ret


class RpcTimeoutRegistry(RpcMethodsRegistry):
    def __init__(self):
        super(RpcTimeoutRegistry, self).__init__()

    def add_method(self, fun, timeout, name=None):
        '''
        Adds tuple (method, timeout) to timeout registry. Formats timeout to Epoch time.

        :param fun    : method callback to be added to registry.
        :param timeout: timeout in seconds. Will be converted to epoch time.
        :param name   : if provided, 'fun' will be stored under this same in registry.
                        If not provided will be genereated automaticaly.
        '''
        if not name:
            name = self.get_rpc_public_name(fun)
        self.registry[name] = (fun, timeout + time.time())
        return name

    def del_method(self, name):
        return self.registry.pop(name, None)

    def pop_all_expired(self):
        '''
        Returns a list of callback functions of cmds/events which timeout expired
        and removes them from registry.
        '''
        expired = []
        try:
            now = time.time()
            for key, (callback, timeout) in list(self.registry.items()):
                if now >= timeout:
                    expired.append(callback)
                    self.registry.pop(key, None)
        except AttributeError:
            # Fix for NoneType object 'time' during server shutdown
            print("[EXC] RpcTimeoutRegistry::pop_all_expired: AttributeError")

        return expired


class RpcClient(object):
    def __init__(self, protocol, transport, methodsRegistry, timeoutRegistry, logger):
        super(RpcClient, self).__init__()
        self.protocol = protocol
        self.transport = transport
        self.actionQueue = Queue.Queue()
        self.goOnEvent = threading.Event()
        self.logger = logger
        self.goOnEvent.set()
        self.rpcServer = RpcServer(protocol=protocol,
                                   transport=transport,
                                   methodsRegistry=methodsRegistry,
                                   timeoutRegistry=timeoutRegistry,
                                   actionQueue=self.actionQueue,
                                   goOnEvent=self.goOnEvent,
                                   logger=self.logger)
        self.rpcServer.daemon = True
        self.rpcServer.start()
        self.debug_event(info="CONSTRUCTED", owner="[%s]" % self.__class__.__name__)

    def debug_event(self, *args, **kwargs):
        if self.logger:
            self.logger.debug_event(*args, **kwargs)

    def __del__(self):
        try:
            self.stop()
            self.debug_event(info="DELETED", owner="[%s]" % self.__class__.__name__)
        except Exception as exc:
            #  Do not throw NoneType race condition exceptions during transport destruction
            print("[EXC] RpcClient::__del__: %s" % exc)

    def stop(self):
        '''
        Stops rpc server.
        '''
        self.goOnEvent.clear()
        threading.Thread.join(self.rpcServer)
        self.debug_event(info="STOPPED", owner="[%s]" % self.__class__.__name__)

    def is_running(self):
        '''
        Check if running
        '''
        return self.rpcServer.is_running()

    def call(self, method, notification=False, timeout=3, silent=False, *args, **kwargs):
        '''
        Call rpc
        '''
        req = self.protocol.create_request(method, notification, silent=silent, *args, **kwargs)
        result = None

        if not self.is_running():
            if self.logger:
                self.logger.debug_msg_flow(info="RPCServer is down. Not putting to actionQ:", data=req, owner="[%s]" % self.__class__.__name__)
            return None

        recvQueue = None if notification else Queue.Queue()
        self._send(req, notification, timeout, recvQueue)
        if not notification:
            result = self._recv(timeout, recvQueue)
            if self.logger:
                self.logger.debug_msg_flow(info="Result from recvQ:", data=result, owner="[%s]" % self.__class__.__name__)
#       result = {'status': 'started'}
        return result

    def _send(self, request, notification, timeout=None, recvQueue=None):
        serverAction = None
        if notification:
            serverAction = RpcServerActionNotify(request)
        else:
            serverAction = RpcServerActionRequest(request, timeout, recvQueue)
        if self.logger:
            self.logger.debug_msg_flow(info="Action to actionQ:", data=serverAction, owner="[%s]" % self.__class__.__name__)
        self.actionQueue.put(serverAction)

    def _recv(self, timeout, recvQueue):
        try:
            to = 0
            while self.goOnEvent.is_set():
                try:
                    if recvQueue.empty():
                        if to <= timeout:
                            time.sleep(0.01)
                            to += 0.01
                        else:
                            print("[RAI] RpcClient::_recv: ErrTransportTimeout: (timeout=%s)" % timeout)
                            raise ErrTransportTimeout
                    else:
                        response = recvQueue.get(block=False)
                        return response.result()
                except Queue.Empty:
                    print("[EXC] RpcClient::_recv: Queue.Empty (timeout=%s)" % timeout)
        except ErrTransportTimeout:
            print("[EXC][RAI] RpcClient::_recv: ErrTransportTimeout -> ErrRpcTimeout (timeout=%s)" % timeout)
            raise ErrRpcTimeout()
        except Queue.Empty:
            print("[EXC][RAI] RpcClient::_recv: Queue.Empty -> ErrRpcTimeout (tmeout=%s)" % timeout)
            raise ErrRpcTimeout()


class RpcServerAction(object):
    pass


class RpcServerActionStop(RpcServerAction):
    def __str__(self):
        return "action-stop"

    def __repr__(self):
        return "<action-stop>"


# We need RpcServerActionNotify and RpcServerActionRequest even if both carry '.request'
# and inside this request we see if it is notification or not
# We need both below since RpcServerActionRequest carries timeout and responseQueue
# The two fields don't belong conceptualy to RpcRequest - they are just processing aspects, not data aspects
class RpcServerActionNotify(RpcServerAction):
    '''
    Envelope that carries notification (no 'id' field).
    '''

    def __init__(self, request):
        super(RpcServerActionNotify, self).__init__()
        self.request = request  # RpcRequest with .notification = True

    def __eq__(self, other):
        if other is None:
            return False
        return self.request == other.request

    def __str__(self):
        return "action-notify(%s)" % self.request

    def __repr__(self):
        return "<action-notify(%s)>" % self.request


class RpcServerActionRequest(RpcServerAction):
    '''
    Envelope that carries request (requires response from other side).
    '''

    def __init__(self, request, timeout, responseQueue):
        super(RpcServerActionRequest, self).__init__()
        self.request = request  # RpcRequest with .notification = False
        self.timeout = timeout
        self.responseQueue = responseQueue

    def __eq__(self, other):
        if other is None:
            return False
        return ((self.request == other.request)
                and (self.timeout == other.timeout)
                and (self.responseQueue == other.responseQueue))

    def __str__(self):
        return "action-request(%s), timeout:%s [sec]" % (self.request, self.timeout)

    def __repr__(self):
        return "<action-request(%s) t[%s]>" % (self.request, self.timeout)


class RpcWaitingRoom(object):
    def __init__(self, protocol):
        super(RpcWaitingRoom, self).__init__()
        self.protocol = protocol
        self.waiting_room = {}  # key is response queue, value is request+responseQueue+responseTimeout

    def store(self, request_action):
        '''
        Store request if it's not already stored.
        Raises RpcRequestAlreadyWaiting or RpcRequestOtherWaiting.
        '''
        responseQueue = request_action.responseQueue
        request = request_action.request
        if responseQueue not in self.waiting_room:
            self.waiting_room[responseQueue] = request_action
        else:
            already_waiting_request = self.waiting_room[responseQueue].request
            if (request == already_waiting_request):
                raise RpcRequestAlreadyWaiting(request)
            else:
                raise RpcRequestOtherWaiting(request, already_waiting_request)

    def find_awaiting4(self, response):
        '''
        Find request for given response
        '''
        for responseQueue in self.waiting_room:
            request_action = self.waiting_room[responseQueue]
            request = request_action.request
            if self.protocol.responds(response, request):
                request_action = self.waiting_room.pop(responseQueue)
                return request_action
        return None


class RpcServer(threading.Thread):
    def __init__(self, protocol, transport, methodsRegistry, timeoutRegistry, actionQueue, goOnEvent, logger):
        super(RpcServer, self).__init__(name='RpcL_server')
        self.protocol = protocol
        self.transport = transport
        self.methodsRegistry = methodsRegistry
        self.timeoutRegistry = timeoutRegistry
        self.waiting_room = RpcWaitingRoom(protocol)

        self.goOnEvent = goOnEvent
        self.actionQueue = actionQueue
        self.logger = logger
        self.transport.open(self.goOnEvent)
        self.debug_event(info="CONSTRUCTED", owner="[%s]" % self.__class__.__name__)

    def debug_event(self, *args, **kwargs):
        if self.logger:
            self.logger.debug_event(*args, **kwargs)

    def debug_msg_flow(self, *args, **kwargs):
        if self.logger:
            self.logger.debug_msg_flow(*args, **kwargs)

    def __del__(self):
        self.debug_event(info="DELETED", owner="[%s]" % self.__class__.__name__)

    def is_running(self):
        '''
        Return server run status
        '''
        return self.goOnEvent.is_set()

    def get_action(self):
        '''
        Must be non-blocking - return None if no action to perform and keep looping.
        '''
        action = None
        try:
            if self.actionQueue.empty():
                return None
            action = self.actionQueue.get(block=False)
            self.debug_msg_flow(info="Action from actionQ:", data=action, owner="[%s]" % self.__class__.__name__)
        except Queue.Empty:
            print("[EXC] RpcServer::get_action: Queue.Empty")
        return action

    def run(self):
        '''
        Run the server
        '''
        try:
            self.debug_event(info="STARTED", owner="[%s]" % self.__class__.__name__)
            self._run()
        finally:
            self.debug_event(info="FINISHED", owner="[%s]" % self.__class__.__name__)

    def _run(self):
        try:
            while self.is_running():
                self.handle_timeouts()
                self.handle_action()
                try:
                    data = self.transport.recv(timeout=0.01)
                    if data:
                        self.handle_remote_data(data)
                except ErrTransportTimeout:
                    # print("[EXC] RpcServer::_run: ErrTransportTimeout")
                    pass
                except ErrTransport:
                    print("[EXC] RpcServer::_run: ErrTransport")
        except RpcServerStop:
            print("[EXC] RpcServer::_run: RpcServerStop")
        except AttributeError:
            # Fix exception during server shutdown
            print("[EXC] RpcServer::_run: AttributeError")
        except Exception as exc:
            print("[EXC][RAI] RpcServer::_run: %s" % exc)
            raise

    def handle_timeouts(self):
        '''
        Get a list of callbacks of all commands/events that timeouted and call them.
        '''
        expired = self.timeoutRegistry.pop_all_expired()
        for timeout_callback in expired:
            timeout_callback()

    def handle_action(self):
        '''
        Encode and send msg from actionQueue to transport layer.
        '''
        action = self.get_action()
        if isinstance(action, RpcServerActionStop):
            raise RpcServerStop
        if isinstance(action, RpcServerActionNotify):
            protocol_encoded_data = self.protocol.encode(action.request)
            self.transport.send(protocol_encoded_data)
        elif isinstance(action, RpcServerActionRequest):
            protocol_encoded_data = self.protocol.encode(action.request)
            self.waiting_room.store(request_action=action)
            self.transport.send(protocol_encoded_data)

    def handle_remote_data(self, data):
        '''
        Decode rpc call from remote and perform it.
        '''
        try:
            rpc_msg = self.protocol.decode(protocol_formated_msg=data)
        except ErrProtocol as err_p:
            print("[EXC] RpcServer::handle_remove_data: %s protocol can't decode data:\n%s\nerr: %s" % (self.protocol, data, err_p))
            return
        if isinstance(rpc_msg, JsonRpcResponse):
            requestAction = self.waiting_room.find_awaiting4(rpc_msg)
            if requestAction:
                responseQueue = requestAction.responseQueue
                responseQueue.put(rpc_msg)
        elif isinstance(rpc_msg, JsonRpcRequest):
            request = rpc_msg
            if request.notification:
                method2call = self.methodsRegistry.get_method(request.method)
                if method2call:
                    self._spawn(method2call, request.args, request.kwargs)

    def _spawn(self, method2call, args, kwargs):
        method2call(*args, **kwargs)


class JsonEncoder(object):
    @staticmethod
    def decode(rpc_formated_data):
        '''
        Decode from JSON string to Python structures (dict, list, ...)
        '''
        try:
            data = json.loads(rpc_formated_data)
            return data
        except ValueError as e:
            print("[EXC] JsonEncoder::decode: ValueError")
            raise ErrJsonRpcDecodeError(e)

    @staticmethod
    def encode(data):
        '''
        Encode Python structures (dict, list, ...) into JSON string
        '''
        try:
            json_str = json.dumps(data, sort_keys=True, separators=(',', ':'))
            rpc_formated_data = json_str
            return rpc_formated_data
        except ValueError as e:
            print("[EXC] JsonEncoder::encode: ValueError")
            print(e)
        except TypeError as e:
            print("[EXC] JsonEncoder::encode: TypeError")
            print(e)
